<?php require __DIR__.'/partials/header.php';$mincap=(float)($_GET['mincap']??0);$maxpe=(float)($_GET['maxpe']??0);$rows=[];try{$sql='SELECT * FROM stocks WHERE 1';$args=[];if($mincap>0){$sql.=' AND market_cap>=?';$args[]=$mincap;}if($maxpe>0){$sql.=' AND pe<=? AND pe>0';$args[]=$maxpe;}$sql.=' ORDER BY market_cap DESC LIMIT 200';$rows=q($sql,$args)->fetchAll();}catch(Throwable $x){} ?><section class="section-head"><div><span class="eyebrow">QUANTITATIVE SCREEN</span><h1>Universe screener</h1></div></section><form class="filterbar card"><label>Min market cap<input type="number" name="mincap" value="<?=e($_GET['mincap']??'')?>"></label><label>Max P/E<input type="number" name="maxpe" value="<?=e($_GET['maxpe']??'')?>"></label><button class="primary">Apply filters</button></form><div class="table-card"><table><thead><tr><th>Symbol</th><th>Market cap</th><th>P/E</th><th>Revenue growth</th><th>EPS growth</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="stock.php?symbol=<?=e($r['symbol'])?>"><b><?=e($r['symbol'])?></b></a></td><td><?=e($r['market_cap'])?></td><td><?=e($r['pe'])?></td><td><?=e($r['revenue_growth'])?></td><td><?=e($r['eps_growth'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/partials/footer.php'; ?>